G1=$(nsg 'fwshift-Brussels-HQ') || exit 1
# attach fwshift-Brussels-HQ-2: 10.10.20.0/24
G2=$(nsg 'fwshift-Brussels-HQ-2') || exit 1
# attach fwshift-Antwerp-DC: 10.20.0.0-10.20.0.9 10.20.0.11-10.20.0.19 10.20.0.21-10.20.0.255
G3=$(nsg 'fwshift-Antwerp-DC') || exit 1
# attach fwshift-Antwerp-DC-2: 10.20.0.10 10.20.0.20
G4=$(nsg 'fwshift-Antwerp-DC-2') || exit 1
# attach fwshift-Antwerp-DC-Routed-lab: 10.20.30.0/24
G5=$(nsg 'fwshift-Antwerp-DC-Routed-lab') || exit 1
# attach fwshift-Ghent-Plant-LAN: 10.30.0.0/24
G6=$(nsg 'fwshift-Ghent-Plant-LAN') || exit 1
# attach fwshift-Leuven-Lab: 10.40.0.0/24
G7=$(nsg 'fwshift-Leuven-Lab') || exit 1
