FWSHIFT_JSON
rules "$G2" <<'FWSHIFT_JSON'
[{"description": "FWShift: inside Brussels-HQ range 2", "direction": "INGRESS", "isStateless": false, "protocol": "all", "source": "10.10.20.0/24", "sourceType": "CIDR_BLOCK"}, {"description": "FWShift: inside Brussels-HQ range 2", "destination": "10.10.20.0/24", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "isStateless": false, "protocol": "all"}, {"description": "FWShift: Allow HQ to DC servers", "destination": "10.20.0.10/32", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "isStateless": false, "protocol": "6", "tcpOptions": {"destinationPortRange": {"max": 443, "min": 443}}}, {"description": "FWShift: Allow HQ to DC servers", "destination": "10.20.0.20/32", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "isStateless": false, "protocol": "6", "tcpOptions": {"destinationPortRange": {"max": 443, "min": 443}}}, {"description": "FWShift: Allow HQ to DC servers", "destination": "10.20.0.10/32", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "isStateless": false, "protocol": "6", "tcpOptions": {"destinationPortRange": {"max": 8443, "min": 8443}}}, {"description": "FWShift: Allow HQ to DC servers", "destination": "10.20.0.20/32", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "isStateless": false, "protocol": "6", "tcpOptions": {"destinationPortRange": {"max": 8443, "min": 8443}}}]
FWSHIFT_JSON
rules "$G3" <<'FWSHIFT_JSON'
[{"description": "FWShift: inside Antwerp-DC range 1", "direction": "INGRESS", "isStateless": false, "protocol": "all", "source": "10.20.0.0/24", "sourceType": "CIDR_BLOCK"}, {"description": "FWShift: inside Antwerp-DC range 1", "destination": "10.20.0.0/24", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "isStateless": false, "protocol": "all"}]
FWSHIFT_JSON
