[{"description": "FWShift: inside Antwerp-DC range 1", "direction": "INGRESS", "isStateless": false, "protocol": "all", "source": "10.20.0.0/24", "sourceType": "CIDR_BLOCK"}, {"description": "FWShift: Allow HQ to DC servers", "direction": "INGRESS", "isStateless": false, "protocol": "6", "source": "10.10.0.0/24", "sourceType": "CIDR_BLOCK", "tcpOptions": {"destinationPortRange": {"max": 443, "min": 443}}}, {"description": "FWShift: Allow HQ to DC servers", "direction": "INGRESS", "isStateless": false, "protocol": "6", "source": "10.10.20.0/24", "sourceType": "CIDR_BLOCK", "tcpOptions": {"destinationPortRange": {"max": 443, "min": 443}}}, {"description": "FWShift: Allow HQ to DC servers", "direction": "INGRESS", "isStateless": false, "protocol": "6", "source": "10.10.0.0/24", "sourceType": "CIDR_BLOCK", "tcpOptions": {"destinationPortRange": {"max": 8443, "min": 8443}}}, {"description": "FWShift: Allow HQ to DC servers", "direction": "INGRESS", "isStateless": false, "protocol": "6", "source": "10.10.20.0/24", "sourceType": "CIDR_BLOCK", "tcpOptions": {"destinationPortRange": {"max": 8443, "min": 8443}}}, {"description": "FWShift: inside Antwerp-DC range 1", "destination": "10.20.0.0/24", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "isStateless": false, "protocol": "all"}]
